() => {
  const el = document.querySelector('[aria-label="Incident report content"]') || document.activeElement;
  function describe(e) {
    if (!e) return null;
    return {
      tag: e.tagName,
      role: e.getAttribute('role'),
      contentEditable: e.contentEditable,
      className: e.className,
      isTextarea: e.tagName === 'TEXTAREA',
      isInput: e.tagName === 'INPUT',
    };
  }
  const found = document.querySelectorAll('textarea, input, [contenteditable="true"]');
  return {
    active: describe(el),
    nativeEditingSurfaces: Array.from(found).map(describe),
  };
}

