() => {
  const editor = document.querySelector('[aria-label="Incident report content"]');
  function walk(e, depth) {
    if (depth > 4) return null;
    return {
      tag: e.tagName,
      cls: e.className,
      text: e.childNodes.length && e.childNodes[0].nodeType === 3 ? e.textContent.slice(0,40) : undefined,
      rect: e.getBoundingClientRect ? (()=>{const r=e.getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height};})() : null,
      children: Array.from(e.children || []).slice(0,3).map(c => walk(c, depth+1))
    };
  }
  return walk(editor, 0);
}

